 local guild=guildContext or HolyStorm.Data.GuildStore:GetCurrentRosterSummary();local member=guild and guild.roster and guild.roster[characterUUID]
 return{characterUUID=characterUUID,name=normalized.name or character.name,realm=normalized.realm or character.realm,fullName=normalized.fullName or character.name,normalizedFullName=normalized.normalizedFullName,classFile=character.classFile or(member and member.classFile),level=character.level or(member and member.level),guildId=member and guild.id or character.guild,guildRankIndex=member and member.rankIndex or character.guildRankIndex,relationship={source=source,confirmedAt=source==self.sources.OWNER and now()or nil}}
end
function TwinkCore:EnsureAccount(accountUUID)
 if not validId(accountUUID)then return nil end;local account=self.accounts[accountUUID];if not account then account={accountUUID=accountUUID,characters={},visibility=self.visibility.ALL,ownerVersion=0,version=0,updatedAt=0};self.accounts[accountUUID]=account end
 account.accountUUID=accountUUID;account.characters=type(account.characters)=="table"and account.characters or{};account.visibility=account.visibility==self.visibility.GUILD_ONLY and self.visibility.GUILD_ONLY or self.visibility.ALL;account.ownerVersion=tonumber(account.ownerVersion or account.version)or 0;account.version=account.ownerVersion;return account
end
