function TwinkCore:CanAdmin(permission,actorGuid)local playerId=actorGuid and(HolyStorm.Data.PlayerStore:GetCharacterOwner(actorGuid)or actorGuid);local engine=HolyStorm.PermissionEngine or HolyStorm.Policy;return engine:Can(permission,playerId,actorGuid)end
