   return out
  end,
  export=function(id)return TwinkCore:GetAdminPayload(id)end,
  validate=function(payload,meta,id)return TwinkCore:ValidateAdminPayload(payload,meta,id)end,
  authorize=function(payload,meta)local permission=payload.operation=="REMOVE"and"twinks-remove"or"twinks-assign";return TwinkCore:CanAdmin(permission,meta.owner)end,
  import=function(id,payload)return TwinkCore:ApplyAdministrativePayload(id,payload)end,
  updateEvent="HS_TWINK_ADMIN_SYNC_UPDATED",
 })
end
function TwinkCore:MigrateAccounts()
 for accountUUID,account in pairs(self.accounts)do if type(accountUUID)~="string"or type(account)~="table"then self.accounts[accountUUID]=nil else account=self:EnsureAccount(accountUUID);local migrated={};for guid,value in pairs(account.characters)do if validId(guid)then if type(value)=="table"and value.characterUUID==guid and value.relationship then migrated[guid]=value else local source=accountUUID==self.localAccountUUID and self.sources.OWNER or account.ownerGuid and self.sources.OWNER or self.sources.ADMIN;local entry=self:CompactIdentity(guid,source);if source==self.sources.ADMIN then entry.relationship={source=source,assignedBy="legacy-migration",assignedAt=tonumber(account.updatedAt)or now(),adminVersion=1}end;migrated[guid]=entry end;self.relationships[guid]=accountUUID;HolyStorm.PlayerData:GetOwners()[guid]=accountUUID end end;account.characters=migrated;account.mainCharacterUUID=account.mainCharacterUUID or account.mainCharacter;account.mainCharacter=nil;account.mainIsManual=account.mainIsManual==true or account.mainCharacterUUID~=nil;account.visibility=account.visibility==self.visibility.GUILD_ONLY and self.visibility.GUILD_ONLY or self.visibility.ALL;account.ownerVersion=tonumber(account.ownerVersion or account.version)or 0;account.version=account.ownerVersion;account.issuedBy=account.issuedBy or account.ownerGuid or account.mainCharacterUUID or next(account.characters);account.relayable=account.relayable~=false end end
end
function TwinkCore:Initialize()
 local root=HolyStorm.PlayerData:GetRoot();root.accounts=type(root.accounts)=="table"and root.accounts or root.players or{};root.players=root.accounts;root.characterAccounts=type(root.characterAccounts)=="table"and root.characterAccounts or root.characterOwners or{};root.characterOwners=root.characterAccounts;root.adminTwinkTombstones=type(root.adminTwinkTombstones)=="table"and root.adminTwinkTombstones or{};self.accounts,self.relationships,self.adminTombstones=root.accounts,root.characterAccounts,root.adminTwinkTombstones
 local accountUUID=root.localAccountUUID or HolyStorm.db.global.localAccountUUID or HolyStorm.db.global.localPlayerId;if not validId(accountUUID)then accountUUID=self:CreateAccountUUID()end;root.localAccountUUID=accountUUID;HolyStorm.db.global.localAccountUUID=accountUUID;HolyStorm.db.global.localPlayerId=accountUUID;self.localAccountUUID=accountUUID;self:EnsureAccount(accountUUID);self:MigrateAccounts()
 if HolyStorm.Rules then
  HolyStorm.Rules:RegisterField("twink-core","account.uuid",{type="string",name=L["RULE_FIELD_ACCOUNT_UUID"],nameKey="RULE_FIELD_ACCOUNT_UUID",description=L["RULE_FIELD_ACCOUNT_UUID_DESC"],descriptionKey="RULE_FIELD_ACCOUNT_UUID_DESC",category=L["ACCOUNT_MAIN"],dependencies={"twinks"},resolver=function(context)return context.accountUUID end})
  HolyStorm.Rules:RegisterField("twink-core","account.isMain",{type="boolean",name=L["RULE_FIELD_ACCOUNT_MAIN"],nameKey="RULE_FIELD_ACCOUNT_MAIN",description=L["RULE_FIELD_ACCOUNT_MAIN_DESC"],descriptionKey="RULE_FIELD_ACCOUNT_MAIN_DESC",category=L["ACCOUNT_MAIN"],dependencies={"twinks"},resolver=function(context)local account=context.accountUUID;if not account or not context.characterUUID then return nil,"MISSING_IDENTITY"end;return context.characterUUID==TwinkCore:GetAccountMain(account)end})
  HolyStorm.Rules:RegisterField("twink-core","character.mainTwinkStatus",{type="enum",name=L["RULE_FIELD_MAIN_STATUS"],nameKey="RULE_FIELD_MAIN_STATUS",description=L["RULE_FIELD_MAIN_STATUS_DESC"],descriptionKey="RULE_FIELD_MAIN_STATUS_DESC",category=L["ACCOUNT_MAIN"],dependencies={"twinks"},values={"MAIN","TWINK"},resolver=function(context)local guid=context.characterUUID or context.character and context.character.guid;local account=guid and TwinkCore:GetAccountUUIDForCharacter(guid);local main=account and TwinkCore:GetAccountMain(account);return guid and main and(main==guid and"MAIN"or"TWINK")or nil end})
  HolyStorm.Rules:RegisterAlias("twink-core","mainTwinkStatus","character.mainTwinkStatus")
 end
 HolyStorm.Tasks:RegisterTaskType("TwinkCore.RecalculateGuildMains",{name=L["TASK_TWINK_RECALCULATE_GUILD_MAINS"],localizedNameKey="TASK_TWINK_RECALCULATE_GUILD_MAINS",module="TwinkCore",priority=30,executionMode="UNIQUE",execute=function()return TwinkCore:RecalculateGuildMains()end})
 HolyStorm.Events:Register("HS_ROSTER_UPDATED","twink-core",function()TwinkCore:QueueGuildMainRecalculation("HS_ROSTER_UPDATED")end);HolyStorm.Events:Register("HS_CHARACTER_UPDATED","twink-core-identity",function(_,guid)if guid==UnitGUID("player")then TwinkCore:ConfirmLocalCharacter(guid)end end)
